WITH orders AS ( SELECT Venda, "Razão Social" AS cliente, MIN(Emissão) AS order_date FROM vendas GROUP BY Venda, "Razão Social" ), orders_2026 AS ( SELECT Venda, cliente FROM orders WHERE strftime('%Y', order_date) = '2026' ), orders_2026_view AS ( SELECT DISTINCT pedido AS Venda, cliente FROM pedidos_efetivos WHERE strftime('%Y', emissao) = '2026' ) SELECT o.cliente, ROUND(100.0 * (COUNT(DISTINCT o.Venda) - COUNT(DISTINCT v.Venda)) / COUNT(DISTINCT o.Venda), 2) AS pct_canceled FROM orders_2026 o LEFT JOIN orders_2026_view v ON o.Venda = v.Venda GROUP BY o.cliente ORDER BY pct_canceled DESC LIMIT 1;